import { useState } from 'react';
import { api } from '../api/client';
import { ApiError } from '../api/types';

export function useRegistrarPresenca(encontroId?: string, apiClient = api) {
  const [codigo, setCodigo] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [error, setError] = useState<{ erro: string; mensagem: string } | null>(null);

  const registrar = async (codigoParam?: string) => {
    const codeToSubmit = codigoParam !== undefined ? codigoParam : codigo;
    if (!encontroId) {
      setError({ erro: 'ENCONTRO_NAO_INFORMADO', mensagem: 'ID do encontro não informado.' });
      return;
    }

    setSubmitting(true);
    setError(null);
    setSuccessMessage(null);

    try {
      const result = await apiClient.registrarPresenca(encontroId, { codigo: codeToSubmit });
      setSubmitting(false);
      setCodigo('');

      if (result.status === 201) {
        setSuccessMessage('Presença registrada agora.');
      } else if (result.status === 200) {
        setSuccessMessage('Presença já estava registrada.');
      } else {
        setSuccessMessage('Presença registrada com sucesso.');
      }
    } catch (err: any) {
      setSubmitting(false);
      setCodigo('');

      if (err instanceof ApiError) {
        let mensagem = err.mensagem;
        if (err.erro === 'NAO_INSCRITO') {
          mensagem = 'Participante não elegível.';
        } else if (err.erro === 'CODIGO_INVALIDO') {
          mensagem = 'Código inválido.';
        } else if (err.erro === 'FORA_DA_JANELA') {
          mensagem = 'Fora do horário permitido.';
        }
        setError({ erro: err.erro, mensagem });
      } else {
        setError({
          erro: 'ERRO_REDE',
          mensagem: 'Sem conexão / Erro de rede',
        });
      }
    }
  };

  return {
    codigo,
    setCodigo,
    submitting,
    successMessage,
    error,
    registrar,
  };
}

import React from 'react';
import { useRegistrarPresenca } from '../hooks/useRegistrarPresenca';
import { api } from '../api/client';

interface RegistrarPresencaProps {
  encontroId?: string;
  id?: string;
  apiClient?: typeof api;
}

export function RegistrarPresenca({
  encontroId,
  id,
  apiClient = api,
}: RegistrarPresencaProps) {
  const targetId = encontroId || id;
  const {
    codigo,
    setCodigo,
    submitting,
    successMessage,
    error,
    registrar,
  } = useRegistrarPresenca(targetId, apiClient);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    registrar();
  };

  return (
    <section className="registrar-presenca-container" data-testid="registrar-presenca-container">
      <div className="page-heading">
        <div>
          <span className="eyebrow">Participante</span>
          <h2>Registrar Presença</h2>
          <p>Digite o código do encontro fornecido pela organização para registrar sua presença.</p>
        </div>
      </div>

      {successMessage && (
        <div className="success-message" role="status" aria-live="polite" data-testid="success-message">
          {successMessage}
        </div>
      )}

      {error && (
        <div className="error-message" role="alert" data-testid="error-message">
          <strong>Erro ({error.erro}):</strong> <span>{error.mensagem}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="form-card">
        <div className="field">
          <label htmlFor="codigo-input">Código do Encontro:</label>
          <input
            id="codigo-input"
            type="text"
            value={codigo}
            onChange={(e) => setCodigo(e.target.value)}
            placeholder="Ex.: K7M2QX"
            required
            disabled={submitting}
            data-testid="codigo-input"
          />
        </div>

        <div className="form-actions">
          <button
            type="submit"
            disabled={submitting || !codigo.trim()}
            className="button button--primary"
            data-testid="submit-button"
          >
            {submitting ? 'Registrando...' : 'Registrar Presença'}
          </button>
        </div>
      </form>
    </section>
  );
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { RegistrarPresenca } from './RegistrarPresenca';
import { api } from '../api/client';
import { ApiError } from '../api/types';

describe('RegistrarPresenca Component', () => {
  beforeEach(() => {
    vi.restoreAllMocks();
  });

  it('deve registrar presença com sucesso 201 e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockResolvedValue({
      presenca: {
        id: 'pre_1',
        encontroId: 'enc_1',
        participanteId: 'p-carla',
        origem: 'qr',
        lidoEm: '2026-10-19T10:00:00-03:00',
        registradaEm: '2026-10-19T10:00:01-03:00',
        justificativa: null,
      },
      status: 201,
    });

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    const submitBtn = screen.getByTestId('submit-button');

    await userEvent.type(input, 'K7M2QX');
    expect(input).toHaveValue('K7M2QX');

    fireEvent.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByTestId('success-message')).toHaveTextContent('Presença registrada agora.');
    });

    expect(registrarPresencaMock).toHaveBeenCalledWith('enc_1', { codigo: 'K7M2QX' });
    expect(input).toHaveValue('');
  });

  it('deve lidar com sucesso 200 (idempotência - presença já existia) e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockResolvedValue({
      presenca: {
        id: 'pre_1',
        encontroId: 'enc_1',
        participanteId: 'p-carla',
        origem: 'qr',
        lidoEm: '2026-10-19T10:00:00-03:00',
        registradaEm: '2026-10-19T10:00:01-03:00',
        justificativa: null,
      },
      status: 200,
    });

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'K7M2QX');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      expect(screen.getByTestId('success-message')).toHaveTextContent('Presença já estava registrada.');
    });

    expect(input).toHaveValue('');
  });

  it('deve tratar erro NAO_INSCRITO e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new ApiError(403, 'NAO_INSCRITO', 'Participante não inscrito nesta atividade.')
    );

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'K7M2QX');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      const errorEl = screen.getByTestId('error-message');
      expect(errorEl).toBeInTheDocument();
      expect(errorEl).toHaveTextContent('NAO_INSCRITO');
      expect(errorEl).toHaveTextContent('Participante não elegível.');
    });

    expect(input).toHaveValue('');
  });

  it('deve tratar erro CODIGO_INVALIDO e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new ApiError(422, 'CODIGO_INVALIDO', 'Código incorreto.')
    );

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'WRONG1');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      const errorEl = screen.getByTestId('error-message');
      expect(errorEl).toBeInTheDocument();
      expect(errorEl).toHaveTextContent('CODIGO_INVALIDO');
      expect(errorEl).toHaveTextContent('Código inválido.');
    });

    expect(input).toHaveValue('');
  });

  it('deve tratar erro FORA_DA_JANELA e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new ApiError(422, 'FORA_DA_JANELA', 'Fora do horário.')
    );

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'K7M2QX');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      const errorEl = screen.getByTestId('error-message');
      expect(errorEl).toBeInTheDocument();
      expect(errorEl).toHaveTextContent('FORA_DA_JANELA');
      expect(errorEl).toHaveTextContent('Fora do horário permitido.');
    });

    expect(input).toHaveValue('');
  });

  it('deve tratar erro de rede / sem conexão e limpar o campo', async () => {
    const registrarPresencaMock = vi.fn().mockRejectedValue(
      new Error('Failed to fetch')
    );

    const fakeClient = {
      ...api,
      registrarPresenca: registrarPresencaMock,
    };

    render(<RegistrarPresenca encontroId="enc_1" apiClient={fakeClient} />);

    const input = screen.getByTestId('codigo-input');
    await userEvent.type(input, 'K7M2QX');
    fireEvent.click(screen.getByTestId('submit-button'));

    await waitFor(() => {
      const errorEl = screen.getByTestId('error-message');
      expect(errorEl).toBeInTheDocument();
      expect(errorEl).toHaveTextContent('ERRO_REDE');
      expect(errorEl).toHaveTextContent('Sem conexão / Erro de rede');
    });

    expect(input).toHaveValue('');
  });
});

